using Essco.Application.Liquidations;using Essco.Application.Security;using Essco.Domain.Liquidations;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;namespace Essco.Web.Pages.Liquidations;[Authorize(Policy=Permissions.LiquidationDifferences)]public sealed class SummaryModel(LiquidationService service):PageModel{public Liquidation Liquidation{get;private set;}=null!;public LiquidationSummary Summary{get;private set;}=null!;[TempData]public string?StatusMessage{get;set;}public async Task<IActionResult>OnGetAsync(LiquidationKind kind,int number,CancellationToken t){var x=(await service.ListAsync(new(kind,Consecutive:number,IncludeAnnulled:true),t)).FirstOrDefault();var s=await service.GetSummaryAsync(kind,number,t);if(x is null||s is null)return NotFound();Liquidation=x;Summary=s;return Page();}public async Task<IActionResult>OnPostRecalculateAsync(LiquidationKind kind,int number,CancellationToken t){StatusMessage=await service.RecalculateAsync(kind,number,t)?"Resultado recalculado.":"No fue posible recalcular.";return RedirectToPage(new{kind,number});}}
